pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 blockNumber, uint256 timeIncrement) public {
        // Restrict to admissible domain: blockNumber >= 1, timeIncrement >= 1 to ensure block.timestamp > 0
        vm.assume(blockNumber >= 1);
        vm.assume(blockNumber <= type(uint64).max);
        vm.assume(timeIncrement >= 1);
        vm.assume(timeIncrement <= type(uint64).max);

        // Setup: move to a block where block.number % 15 == 0, so the first eligible call triggers transfer.
        // We want blockNumber itself to be divisible by 15.
        uint256 startBlock = (blockNumber / 15) * 15;
        vm.assume(startBlock > 0);
        vm.roll(startBlock);
        vm.warp(timeIncrement);

        address actor = address(0x1234);
        vm.deal(actor, 20 ether);

        // First call: succeeds, sets pastBlockTime
        vm.prank(actor);
        (bool ok1,) = address(c).call{value: 10 ether}("");
        assertTrue(ok1);

        // Second call in the same block: reference reverts (require(block.timestamp > pastBlockTime) fails),
        // buggy passes (require(true)), triggering transfer again.
        vm.prank(actor);
        (bool ok2,) = address(c).call{value: 10 ether}("");

        // After the calls, check contract balance.
        // Reference: the second call reverts, so balance = 10 ether.
        // Buggy: second call succeeds and balance is transferred (block.number % 15 == 0), so balance = 0.
        uint256 balanceAfter = address(c).balance;

        // The invariant: the contract must never have zero balance after a failed second call.
        // If second call reverted (ok2 == false), reference holds 10 ether.
        // If second call succeeded (ok2 == true), buggy violates balance == 0.
        // The general rule: after a sequence where the second call reverts, balance remains 10 ether.
        // In buggy, ok2 is true and balance is 0, so assertTrue(balanceAfter >= 10 ether) fails.
        // But we need a single assertion that captures the difference over all admissible inputs.
        // Property: If the second call fails (ok2 == false), then balance must be at least 10 ether.
        // For the buggy version, the second call succeeds, so the antecedent is false, making implication true.
        // We instead assert that the second call's success implies the balance is not 0? That's not a universal property for reference.
        // Better: The reference always ends with balance >= 10 ether (since second call either reverts or succeeds and transfers balance,
        // but if it succeeds, balance becomes 0). Wait, if the second call succeeds in reference (which it cannot under the setup),
        // it would transfer both 10+10=20 ether? We must craft a property that reference always satisfies and buggy violates.
        // In reference, regardless of block number, when two calls are made in the same block,
        // the second call ALWAYS reverts because pastBlockTime is not updated before the timestamp check.
        // Therefore, after any two-call sequence in the same block, the contract balance is exactly the sum of successful call values.
        // The first call always succeeds (given msg.value == 10 ether). So balanceAfter == 10 ether.
        // For buggy, if block.number % 15 == 0, both succeed and the second triggers transfer of entire balance (now 20 ether) to actor.
        // So balanceAfter == 0. If block.number % 15 != 0, both succeed but no transfer, balanceAfter == 20 ether.
        // The property: after the two calls, the contract balance must be exactly 10 ether (the amount from the only successful call).
        // This holds for reference for ALL block numbers. For buggy, it's false when block.number % 15 == 0.
        // So we assert balanceAfter == 10 ether.
        assertEq(balanceAfter, 10 ether);
    }
}

