pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 numCalls, uint256 startBlock) public {
        // admissible domain: at least one call and a reasonable number to avoid blowup
        numCalls = bound(numCalls, 1, 10);
        startBlock = bound(startBlock, 1, 10);
        // ensure the block range contains a block divisible by 15 and at least one candidate for multiple calls in a block
        vm.assume(startBlock % 15 == 1);

        uint256 totalDeposited = 0;
        uint256 totalTransferred = 0;
        address caller = makeAddr("caller");
        vm.deal(caller, 1000 ether);

        for (uint256 i = 0; i < numCalls; i++) {
            // warp to a fresh block for the first call only; subsequent calls stay in the same block
            if (i == 0) {
                vm.roll(startBlock);
            }
            // call fallback with 10 ether
            vm.prank(caller);
            try c.fallback{value: 10 ether}() {
                totalDeposited += 10 ether;
                // if we just triggered a transfer, record it
                if (block.number % 15 == 0) {
                    totalTransferred += address(c).balance + 10 ether; // balance before call was contract's old balance; this equals the whole balance transferred
                }
            } catch {
                // call failed (e.g., pastBlockTime violation), stop trying for this block
                break;
            }
        }

        // rule: contract balance must be at least totalDeposited - totalTransferred,
        // and specifically for the reference it must be >= 10 ether if only one non-transfer call succeeded.
        // Simplified: after the loop, the contract must hold at least 10 ether if only one call succeeded
        // but the bug drains entire balance when two calls succeed in a divisible-by-15 block.
        // A universal invariant: contract balance >= totalDeposited - totalTransferred
        assertTrue(
            address(c).balance >= totalDeposited - totalTransferred,
            "balance invariant violated"
        );
    }
}

