pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 calls, uint256 blockNumber, uint256 timestamp) public {
        // Bound the number of calls to a manageable range
        calls = bound(calls, 1, 50);
        // Block number must be a multiple of 15 to trigger the transfer
        blockNumber = bound(blockNumber, 15, type(uint256).max);
        vm.assume(blockNumber % 15 == 0);
        vm.roll(blockNumber);
        // Timestamp must increase with each call in reference, but we set it before the loop
        // For the buggy version, timestamp doesn't matter, so we just need one valid call to drain
        timestamp = bound(timestamp, 1, type(uint256).max);
        vm.warp(timestamp);

        // Fund the caller with enough ether for one call
        address caller = address(this);
        vm.deal(caller, 10 ether);

        // Perform one fallback call with 10 ether
        vm.prank(caller);
        (bool success, ) = address(c).call{value: 10 ether}("");

        // After the call, check the balance of the contract
        // In the reference, the transfer is triggered, so the balance should be 0
        // In the buggy version, the transfer is also triggered, and the balance should also be 0
        // This doesn't differentiate them. We need a different approach.

        // Let's reconsider: The bug removes the timestamp check, allowing multiple calls in the same block.
        // In the reference, only one call per block is allowed, so the balance after the call is 0.
        // In the buggy version, multiple calls can be made in the same block, but since the transfer sends all balance,
        // subsequent calls would have nothing to transfer, so the balance might still be 0 after one call.
        // The property must be something about the state after a sequence of calls.

        // Property: After any number of successful fallback calls, the contract balance is always a multiple of 10 ether.
        // In reference: each call adds 10 ether, and when block.number % 15 == 0, the entire balance is transferred out,
        // making the balance 0, which is a multiple of 10. In buggy: multiple calls within the same block at a divisible-by-15
        // block can drain all balance, but the first call transfers balance, second call has 0 balance to add, so balance stays 0.
        // Let's try: When block.number % 15 != 0, multiple calls can be made in the buggy version, increasing the balance.
        // In the reference, only one call per block is allowed, so balance at most 10 ether. Bug allows many calls, so balance
        // can be > 10 ether. So a property: balance <= calls * 10 ether? But the transfer can happen, so not always.

        // Let's think: The reference ensures that after any successful call, the block timestamp is strictly increasing,
        // so pastBlockTime is always updated to a value > block.timestamp of the call. The bug sets pastBlockTime to block.timestamp
        // but allows multiple calls with the same timestamp because the require is gone. So pastBlockTime might be the same as
        // block.timestamp after a call. In the reference, pastBlockTime is always < the next block.timestamp for the next call.
        // But we can only read pastBlockTime via its public getter.

        // The difference: pastBlockTime state variable. In reference, after a successful call, pastBlockTime == block.timestamp.
        // In buggy, same. But the reference enforces that subsequent calls must have block.timestamp > pastBlockTime.
        // So if we try to make two calls in the same block, the reference will revert the second call, buggy will succeed.
        // The property can be: The balance of the contract after two calls in the same block at a non-divisible-by-15 block number
        // is 10 ether in reference (second call reverts) and 20 ether in buggy (second call succeeds).
        // But we need a single assertion that works for all inputs.

        // Let's do this: We make exactly 2 calls with the same fuzzed block number and timestamp, where block.number % 15 != 0.
        // Then check balance. Reference: balance == 10 ether (only first call succeeds). Buggy: balance == 20 ether (both succeed).
        // But we don't know exactly what the fuzzer will give, so we generalize: the balance should be EXACTLY 10 ether.
        // Reference always has balance 10 ether (since second reverts), buggy has 20 ether.
        // So assertTrue(address(c).balance == 10 ether).

        // However, we need to ensure the transfer doesn't happen, so block.number % 15 != 0.
        blockNumber = bound(blockNumber, 1, type(uint256).max);
        vm.assume(blockNumber % 15 != 0);
        vm.roll(blockNumber);
        timestamp = bound(timestamp, 1, type(uint256).max);
        vm.warp(timestamp);

        address caller2 = address(0x1234); // different caller to avoid nonce issues? Not needed.
        vm.deal(caller2, 10 ether);

        // First call
        vm.prank(caller2);
        (bool success1, ) = address(c).call{value: 10 ether}("");
        require(success1, "First call failed");

        // Second call in the same block with same timestamp
        address caller3 = address(0x5678);
        vm.deal(caller3, 10 ether);
        vm.prank(caller3);
        (bool success2, ) = address(c).call{value: 10 ether}("");

        // In reference, success2 should be false (revert due to timestamp), so balance should be 10 ether.
        // In buggy, success2 is true, balance 20 ether.
        // So we can assert: if the second call succeeded, the balance must be exactly 20 ether? That's not a general property.
        // We need a property that reference holds and bug breaks. Let's assert that the balance is exactly 10 ether.
        // Reference: balance == 10 ether. Buggy: balance == 20 ether, so assert fails.
        assertTrue(address(c).balance == 10 ether);
    }
}

