import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 blockNum1, uint256 blockNum2) public {
        // Ensure strictly increasing timestamps: set block.timestamp proportional to block numbers
        // and ensure blockNum2 > blockNum1 so timestamp2 > timestamp1
        vm.assume(blockNum1 < blockNum2);
        // Restrict block numbers to reasonable range (don't constrain divisibility condition)
        blockNum1 = bound(blockNum1, 0, 1e12);
        blockNum2 = bound(blockNum2, blockNum1 + 1, 1e12 + 1);

        // Fund an actor
        address actor = address(0x1234);
        vm.deal(actor, 20 ether);

        // Warp to blockNum1 and trigger fallback with 10 ether
        vm.roll(blockNum1);
        vm.warp(blockNum1); // timestamp == blockNum1 (simple monotonic relation)
        vm.prank(actor);
        c.fallback{value: 10 ether}();

        // Warp to blockNum2 (strictly greater timestamp) and trigger fallback again
        vm.roll(blockNum2);
        vm.warp(blockNum2); // timestamp == blockNum2 > blockNum1
        vm.prank(actor);
        c.fallback{value: 10 ether}();

        // After the two calls, check the invariant:
        // If blockNum2 is divisible by 15, reference C would have transferred its entire balance
        // (should be 0), whereas the buggy version leaves balance non-zero.
        // We assert that when blockNum2 % 15 == 0, the contract balance is 0.
        // The buggy version fails this assertion because its balance remains positive.
        if (blockNum2 % 15 == 0) {
            assertEq(address(c).balance, 0);
        } else {
            // For non-divisible blocks, no transfer occurs in either version, balance must be 20 ether
            assertEq(address(c).balance, 20 ether);
        }
    }
}

