import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint256 warpTime, uint256 rollBlock) public {
        vm.assume(warpTime > 0);
        vm.assume(rollBlock > 0);
        amount = bound(amount, 0, 1000 ether);
        vm.deal(address(this), amount);
        vm.warp(warpTime);
        vm.roll(rollBlock);

        uint256 balanceBefore = address(c).balance;
        (bool ok,) = address(c).call{value: amount}("");
        uint256 balanceAfter = address(c).balance;

        if (ok) {
            assertTrue(balanceAfter >= balanceBefore);
        }
    }
}

