pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 actorSeed, uint256 blockNumber, uint256 timestamp) public {
        address actor = address(uint160(uint256(keccak256(abi.encode(actorSeed)))));
        vm.assume(actor != address(0) && actor != address(c) && actor != address(this));
        vm.assume(timestamp > 0);
        vm.assume(blockNumber > 0);
        uint256 amount = 10 ether;
        vm.deal(actor, amount);
        vm.warp(timestamp);
        vm.roll(blockNumber);
        vm.prank(actor);
        (bool success,) = address(c).call{value: amount}("");
        assertTrue(success);
        if(blockNumber % 15 == 0) {
            assertTrue(address(c).balance == 0);
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 blockNum, uint40 blockTimestamp) public {
        // bound to plausible ranges; keep domain wide
        blockNum = uint256(bound(blockNum, 1, type(uint256).max - 1));
        blockTimestamp = uint40(bound(blockTimestamp, 1, type(uint40).max));

        // set block context
        vm.roll(blockNum);
        vm.warp(blockTimestamp);

        // fund a caller
        address caller = address(0xdead);
        vm.deal(caller, 20 ether);

        // first call with 10 ether; must succeed in both versions
        vm.prank(caller);
        (bool ok1, ) = address(c).call{value: 10 ether}("");
        require(ok1, "first call failed");

        // after a successful call, pastBlockTime should equal the block timestamp in the reference,
        // blocking another call in the same block. The mutant sets pastBlockTime to 0, allowing it.
        // We attempt a second call with the same timestamp.
        vm.prank(caller);
        (bool ok2, ) = address(c).call{value: 10 ether}("");

        // Reference: ok2 == false (revert because block.timestamp > pastBlockTime fails)
        // Mutant: ok2 == true (pastBlockTime was 0, check passes)
        assertTrue(!ok2);
    }
}
